    gjendjet: () => L("Gjendjet e lëndës", () => classQ({ "e ngurtë": ["akulli", "guri", "hekuri", "druri"], "e lëngët": ["uji", "qumështi", "vaji", "lëngu i mollës"], "e gaztë": ["avulli i ujit", "ajri", "oksigjeni", "dioksidi i karbonit"] }, "cat", 7, (it) => `Në cilën gjendje e gjejmë zakonisht: ${it}?`)),
    ndryshimet: () => L("Kalimet e gjendjeve", () => { const P = [["shkrirja", "nga e ngurtë në të lëngët"], ["ngrirja", "nga e lëngët në të ngurtë"], ["avullimi", "nga e lëngët në të gaztë"], ["kondensimi", "nga e gaztë në të lëngët"], ["sublimimi", "nga e ngurtë drejtpërdrejt në të gaztë"]]; return shuffle(tableRev(P, (v) => `Si quhet kalimi ${v}?`, 4).concat(tableQ(P, (k) => `Çka ndodh gjatë procesit: ${k}?`, 3))); }),
    shpejtesia: () => L("Shpejtësia", () => repeat(7, () => { const v = R(2, 30), t = R(2, 12); const k = R(0, 2); if (k === 0) return { q: `Një trup përshkon ${v * t} m për ${t} s. Shpejtësia = ? m/s`, opts: so(v, [v * t * t, v + t, v + 1]), ans: String(v), hint: "v = s / t" }; if (k === 1) return { q: `Një biçikletë lëviz ${v} m/s për ${t} s. Rruga = ? m`, opts: so(v * t, [v + t, v * t + v, Math.round(v / t) || 1]), ans: String(v * t), hint: "s = v · t" }; const kmh = pick([36, 54, 72, 90, 108]); return { q: `${kmh} km/h = ? m/s`, opts: so(Math.round(kmh / 3.6), [fmt(kmh * 3.6), Math.round(kmh / 10), Math.round(kmh / 3.6) + 5]), ans: String(Math.round(kmh / 3.6)), hint: "Pjesëto me 3,6." }; })),
