    forca: () => L("Forca dhe pesha (g = 10 N/kg)", () => repeat(7, () => { const m = R(2, 60), a = R(2, 9); return Math.random() < 0.5 ? { q: `Pesha e një trupi me masë ${m} kg = ? N`, opts: so(m * 10, [m, m + 10, m * 100]), ans: String(m * 10), hint: "G = m · g" } : { q: `Trupi ${m} kg merr nxitim ${a} m/s². Forca = ? N`, opts: so(m * a, [m + a, m * a * 10, m * (a + 1)]), ans: String(m * a), hint: "F = m · a" }; })),
